import styles from './TransactionList.module.css';

const TransactionList = ({ transactions }) => {
  return (
    <ul className={styles.list}>
      {transactions.map((transaction, index) => (
        <li key={index} className={styles.item}>
          <p><strong>Descripción:</strong> {transaction.description}</p>
          <p><strong>Monto:</strong> ${transaction.amount}</p>
          <p><strong>Tipo:</strong> {transaction.type === 'income' ? 'Ingreso' : 'Gasto'}</p>
          <p><strong>Día:</strong> {transaction.day}</p>
          <p><strong>Hora:</strong> {transaction.time}</p>
        </li>
      ))}
    </ul>
  );
};

export default TransactionList;
